result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app.py", "content": """"Flask service with a single, uniform JSON error envelope.

Every error response is:
    {"error": {"code": str, "message": str, "request_id": str}}
with Content-Type: application/json.
"""

import uuid

from flask import Flask, g, jsonify

app = Flask(__name__)


def _error_body(code: str, message: str) -> tuple[dict, dict]:
    """Build the envelope and headers shared by all error handlers."""
    request_id = getattr(g, "request_id", None) or uuid.uuid4().hex
    return (
        {"error": {"code": code, "message": message, "request_id": request_id}},
        {"X-Request-ID": request_id},
    )


@app.before_request
def _assign_request_id() -> None:
    g.request_id = uuid.uuid4().hex


def _register_error_handlers(flask_app: Flask) -> None:
    @flask_app.errorhandler(404)
    def _not_found(_e):
        body, headers = _error_body("not_found", "The requested resource was not found.")
        return jsonify(body), 404, headers

    @flask_app.errorhandler(405)
    def _method_not_allowed(e):
        body, headers = _error_body(
            "method_not_allowed",
            f"Method {e.description.split('for this URL')[0].strip()} is not allowed for this URL.",
        )
        # Flask's 405 handler sets Allow; keep it on our JSON response too.
        headers["Allow"] = e.valid_methods
        return jsonify(body), 405, headers

    @flask_app.errorhandler(500)
    @flask_app.errorhandler(Exception)
    def _internal_error(e):
        if isinstance(e, Exception) and not isinstance(e, type(None)):
            flask_app.logger.exception("Unhandled exception")
            message = "An internal server error occurred."
        else:
            message = "An internal server error occurred."
        body, headers = _error_body("internal_error", message)
        return jsonify(body), 500, headers


_register_error_handlers(app)


@app.get("/health")
def health():
    return jsonify({"status": "ok"})


@app.get("/boom")
def boom():
    raise RuntimeError("intentional failure for testing")


if __name__ == "__main__":
    app.run(debug=False)
